<article class="learning-lab">
  <header class="lab-header"><p class="eyebrow">READ · NOTICE · THINK · WRITE</p><h2><?php if (isset($sample)): ?>El objetivo de este taller<?php else: ?><span lang="en"><?= e($lab['title']) ?></span><?php endif; ?></h2><p class="lab-goal"><?= e($lab['goal']) ?></p></header>
